import importlib.util
import json
from pathlib import Path
import re
import sys

_SOURCE = Path(__file__).resolve().parent.parent / "xml" / "xml_source.py"
_spec = importlib.util.spec_from_file_location("stellar_forge_original_xml_source", _SOURCE)
