    native = _xml.parser()
    stack: list[dict] = []
    rows: list[dict] = []
    seen_root = False
    byte_count = 0
    node_count = 0
    text_count = 0
    def start(raw_name, attrs):
        nonlocal seen_root, node_count
        name = _xml.expanded(raw_name)
        node_count += 1
